// The cover's two typefaces as base64 data URIs, embedded so the PDF renderer
// never needs a network fetch -- exactly like the logo and the band beside
// them. Subset to Latin-1 plus Latin Extended-A and the punctuation the kit
// prints, which is what keeps three faces inside a hundred kilobytes; an
// organization name outside that range would fall back, so widen the subset
// rather than adding a second family if that ever happens.
//
// Sources: Instrument Sans and IBM Plex Mono, both SIL Open Font License 1.1,
// taken from Google Fonts as static TrueType instances (the variable font is
// not what @react-pdf/font parses). The subset files these are encoded from
// are in public/pdf/fonts; re-subset from the upstream families and rebuild
// them if the glyph coverage has to grow.

export const INSTRUMENT_SANS_400 =
  "data:font/truetype;base64,"

export const INSTRUMENT_SANS_500 =
  "data:font/truetype;base64,"

export const IBM_PLEX_MONO_400 =
  "data:font/truetype;base64,"
